@@ -1,656 +1,666 @@
 package app

 import (
 	"KNIRVGRAPH/internal/economics"
 	"KNIRVGRAPH/internal/graphchain"
 	"KNIRVGRAPH/internal/network"
 	"KNIRVGRAPH/internal/nrv"
 	"KNIRVGRAPH/internal/p2p"
 	"KNIRVGRAPH/internal/storage"
 	"context"
